import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Autoplay, Pagination } from 'swiper/modules';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import 'swiper/css';
import 'swiper/css/pagination';

const features = [
  {
    key: 'tasmi',
    path: '/tasmi',
    icon: '🎙️',
  },
  { key: 'prayerTimes', icon: '🕋' },
  { key: 'calendar', icon: '📅' },
  { key: 'kaabaClock', icon: '⏰' },
  { key: 'api', icon: '🔗' },
  { key: 'reminders', icon: '🔔' },
  { key: 'tajweed', icon: '📖' },
  { key: 'wordByWord', icon: '🔤' },
  { key: 'audio', icon: '🔊' },
  { key: 'adFree', icon: '🚫' },
  { key: 'tafseer', icon: '📚' },
];

const cardVariants = {
  initial: { opacity: 0, y: 40 },
  animate: { opacity: 1, y: 0 },
};

const FeaturesSlider = () => {
  const { t } = useTranslation('home');
  // Card text comes from locales/<lang>/home.json; cards with a `path` link to their page.
  const items = features.map((f) => ({ ...f, title: t(`features.${f.key}.title`), description: t(`features.${f.key}.description`) }));
  return (
  <div style={{ width: '100%', maxWidth: 900, margin: '0 auto', padding: '2rem 0' }}>
    <Swiper
      modules={[Autoplay, Pagination]}
      spaceBetween={32}
      slidesPerView={1.2}
      centeredSlides
      loop
      autoplay={{ delay: 3500, disableOnInteraction: false }}
      pagination={{ clickable: true }}
      breakpoints={{
        600: { slidesPerView: 2 },
        900: { slidesPerView: 3 },
      }}
      style={{ paddingBottom: 40 }}
    >
      {items.map((feature, idx) => (
        <SwiperSlide key={feature.key}>
          <motion.div
            variants={cardVariants}
            initial="initial"
            whileInView="animate"
            viewport={{ once: true, amount: 0.5 }}
            transition={{ duration: 0.7, delay: idx * 0.1 }}
            whileHover={{ scale: 1.05, boxShadow: '0 8px 32px rgba(0,0,0,0.15)' }}
            style={{
              background: 'white',
              borderRadius: 18,
              boxShadow: '0 2px 16px rgba(0,0,0,0.07)',
              padding: '2.5rem 1.5rem',
              minHeight: 260,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              textAlign: 'center',
              cursor: 'pointer',
              transition: 'box-shadow 0.3s',
            }}
          >
            <div aria-hidden="true" style={{ fontSize: 48, marginBottom: 18 }}>{feature.icon}</div>
            <h3 style={{ fontSize: 22, fontWeight: 600, margin: '0 0 12px' }}>
              {feature.path ? <Link to={feature.path} style={{ color: 'inherit', textDecoration: 'none' }}>{feature.title}</Link> : feature.title}
            </h3>
            <p style={{ color: '#444', fontSize: 16, margin: 0 }}>{feature.description}</p>
          </motion.div>
        </SwiperSlide>
      ))}
    </Swiper>
  </div>
  );
};

export default FeaturesSlider;
